"""Merge Two BSTs — merge two iterative inorder traversals.

Each stack holds the path down the left spine, so pulling the next smallest
value from either tree is O(1) amortised — the merge never materialises either
tree into a list.

Time: O(n + m)   Space: O(h1 + h2)
"""
from typing import List

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def mergeBST(self, root1, root2) -> List[int]:
        def push_left(stack, node):
            while node:
                stack.append(node)
                node = node.left

        s1, s2 = [], []
        push_left(s1, root1)
        push_left(s2, root2)

        out = []
        while s1 or s2:
            if not s2 or (s1 and s1[-1].val <= s2[-1].val):
                node = s1.pop()
                out.append(node.val)
                push_left(s1, node.right)
            else:
                node = s2.pop()
                out.append(node.val)
                push_left(s2, node.right)
        return out
